create table customer_metadata_projections(customer_account_id uuid primary key references customer_accounts(id) on delete cascade,lifecycle_stage text not null check(lifecycle_stage in('onboarding','active','at_risk','churned')),plan_name text,customer_success_owner_id uuid references internal_users(id),renewal_target date,active_member_count int check(active_member_count>=0),last_aggregate_activity_at timestamptz,updated_at timestamptz not null default now());
create table customer_health_signals(id uuid primary key default gen_random_uuid(),customer_account_id uuid not null references customer_accounts(id) on delete cascade,signal_key text not null,signal_value numeric,signal_state text not null check(signal_state in('positive','neutral','warning','critical','unknown')),reason text not null,observed_at timestamptz not null,source text not null,classification text not null default 'operational_metadata' check(classification='operational_metadata'),unique(customer_account_id,signal_key,observed_at));
create table customer_health_snapshots(id uuid primary key default gen_random_uuid(),customer_account_id uuid not null references customer_accounts(id) on delete cascade,score int not null check(score between 0 and 100),computed_category text not null check(computed_category in('healthy','watch','at_risk','critical')),effective_category text not null check(effective_category in('healthy','watch','at_risk','critical')),methodology_version text not null,reasons jsonb not null,missing_information text[] not null default '{}',override_reason text,overridden_by uuid references internal_users(id),computed_at timestamptz not null,unique(customer_account_id,computed_at),check(computed_category=effective_category or (override_reason is not null and overridden_by is not null)));
alter table customer_metadata_projections enable row level security;alter table customer_health_signals enable row level security;alter table customer_health_snapshots enable row level security;
grant select,insert,update on customer_metadata_projections,customer_health_signals,customer_health_snapshots to authenticated;
create policy customer_metadata_select on customer_metadata_projections for select using(is_active_internal_user());create policy customer_metadata_write on customer_metadata_projections for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
create policy customer_health_signals_select on customer_health_signals for select using(is_active_internal_user());create policy customer_health_signals_write on customer_health_signals for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
create policy customer_health_snapshots_select on customer_health_snapshots for select using(is_active_internal_user());create policy customer_health_snapshots_write on customer_health_snapshots for all using(internal_has_role(array['super_admin','operations','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success']::internal_role[]));
